<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class StudentLifeController extends Controller{
 private function ctx(Request $r){$p=$r->attributes->get('academic_period');$u=$r->user();abort_unless($u->student_id,403);$s=DB::table('students')->find($u->student_id);$m=DB::table('student_group_memberships')->where(['student_id'=>$s->id,'academic_period_id'=>$p->id])->first();return [$p,$s,$m?->study_group_id??$s->current_group_id];}
 public function index(Request $r){[$p,$student,$gid]=$this->ctx($r);$news=DB::table('group_news')->where('academic_period_id',$p->id)->where(fn($q)=>$q->whereNull('study_group_id')->orWhere('study_group_id',$gid))->whereNotNull('published_at')->orderByDesc('pinned')->orderByDesc('published_at')->limit(20)->get();$activities=DB::table('activities as a')->leftJoin('activity_registrations as ar',fn($j)=>$j->on('ar.activity_id','=','a.id')->where('ar.student_id','=',$student->id))->where('a.academic_period_id',$p->id)->where(fn($q)=>$q->whereNull('a.study_group_id')->orWhere('a.study_group_id',$gid))->where('a.starts_at','>=',now()->subDay())->select('a.*','ar.status as registration_status')->orderBy('a.starts_at')->get();$practice=DB::table('practice_placements')->where(['academic_period_id'=>$p->id,'student_id'=>$student->id])->orderByDesc('starts_on')->get();return view('student.life',compact('p','student','news','activities','practice'));}
 public function register(Request $r,$activity){[$p,$s,$gid]=$this->ctx($r);$a=DB::table('activities')->find($activity);abort_if(!$a||$a->academic_period_id!=$p->id||($a->study_group_id&&$a->study_group_id!=$gid),404);abort_if($a->status!=='open'||($a->registration_until&&now()->gt($a->registration_until)),409);if($a->capacity){$n=DB::table('activity_registrations')->where('activity_id',$a->id)->where('status','registered')->count();abort_if($n>=$a->capacity,409,'Мест больше нет.');}DB::table('activity_registrations')->updateOrInsert(['activity_id'=>$a->id,'student_id'=>$s->id],['status'=>'registered','registered_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Вы записаны.');}
 public function cancel(Request $r,$activity){[, $s]=$this->ctx($r);DB::table('activity_registrations')->where(['activity_id'=>$activity,'student_id'=>$s->id])->update(['status'=>'cancelled','updated_at'=>now()]);return back()->with('success','Запись отменена.');}
 public function diary(Request $r,$practice){[$p,$s]=$this->ctx($r);$x=DB::table('practice_placements')->where(['id'=>$practice,'student_id'=>$s->id,'academic_period_id'=>$p->id])->first();abort_if(!$x,404);$d=$r->validate(['work_date'=>'required|date','work_description'=>'required|string|max:5000','hours'=>'nullable|numeric|min:0|max:24']);abort_if($d['work_date']<$x->starts_on||$d['work_date']>$x->ends_on,422,'Дата вне периода практики.');DB::table('practice_diary_entries')->updateOrInsert(['practice_placement_id'=>$x->id,'work_date'=>$d['work_date']],array_merge($d,['status'=>'submitted','created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Запись дневника сохранена.');}
}